      { id: 4, body: '[consensus] result=split round=2' }
    ];
    const result = evaluateCouncil({ taskId: 't5', comments, maxRounds: 2 });
    assert.equal(result.next, 'arbitrate');
    assert.equal(result.stage, 'council');
  });

